package com.medtrack.inventory.repository;
import com.medtrack.inventory.entity.InventoryBalance; import jakarta.persistence.LockModeType; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface InventoryBalanceRepository extends JpaRepository<InventoryBalance,UUID> { Optional<InventoryBalance> findByWarehouse_IdAndBatch_Id(UUID warehouseId,UUID batchId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select ib from InventoryBalance ib join fetch ib.batch b where ib.warehouse.id=:warehouseId and b.medicine.id=:medicineId and b.status=com.medtrack.batch.entity.BatchStatus.ACTIVE and b.expiryDate >= CURRENT_DATE and ib.availableQuantity > 0 order by b.expiryDate asc, b.id asc") List<InventoryBalance> lockFefoCandidates(@Param("medicineId") UUID medicineId,@Param("warehouseId") UUID warehouseId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select ib from InventoryBalance ib join fetch ib.batch where ib.warehouse.id=:warehouseId and ib.batch.id=:batchId") Optional<InventoryBalance> lockByWarehouseAndBatch(@Param("warehouseId") UUID warehouseId,@Param("batchId") UUID batchId); Page<InventoryBalance> findByWarehouse_Id(UUID warehouseId,Pageable pageable); }
